{
  "Resources": {
    "SuperCoolAPI": {
      "Properties": {
        "AuthenticationType": "AWS_IAM",
        "IntrospectionConfig": "DISABLED",
        "LogConfig": {
          "CloudWatchLogsRoleArn": {
            "Fn::GetAtt": [
              "SuperCoolAPICloudWatchRole",
              "Arn"
            ]
          },
          "FieldLogLevel": "ALL"
        },
        "Name": "SuperCoolAPI",
        "OwnerContact": "blah-blah",
        "QueryDepthLimit": 10,
        "ResolverCountLimit": 100,
        "Tags": [
          {
            "Key": "graphqlapi:createdBy",
            "Value": "SAM"
          }
        ],
        "Visibility": "PRIVATE"
      },
      "Type": "AWS::AppSync::GraphQLApi"
    },
    "SuperCoolAPICloudWatchRole": {
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Statement": [
            {
              "Action": [
                "sts:AssumeRole"
              ],
              "Effect": "Allow",
              "Principal": {
                "Service": [
                  "appsync.amazonaws.com"
                ]
              }
            }
          ],
          "Version": "2012-10-17"
        },
        "ManagedPolicyArns": [
          {
            "Fn::Sub": "arn:${AWS::Partition}:iam::aws:policy/service-role/AWSAppSyncPushToCloudWatchLogs"
          }
        ]
      },
      "Type": "AWS::IAM::Role"
    },
    "SuperCoolAPISchema": {
      "Properties": {
        "ApiId": {
          "Fn::GetAtt": [
            "SuperCoolAPI",
            "ApiId"
          ]
        },
        "Definition": "type Book {\n    bookName: String\n} \ntype Query { getBook(bookName: String): Book }\n"
      },
      "Type": "AWS::AppSync::GraphQLSchema"
    }
  }
}

AWSTemplateFormatVersion: 2010-09-09

# Simple Step-Function calculator demo.
# The step function calls a lambda function to calculate.
# This state machine expects input in the form:
# {"operator": "add", "operands": [1,2]}

Resources:

  MyStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: Calculator-StateMachine
      DefinitionString: !Sub |-
        {
          "Comment": "Simple Calculator Step Functions Example",
          "StartAt": "state.start.operatorSelector",
          "States": {
            "state.start.operatorSelector": {
              "Type": "Choice",
              "Choices": [
                {
                  "Variable": "$.operator",
                  "StringEquals": "add",
                  "Next": "state.process.operator.add"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "subtract",
                  "Next": "state.process.operator.subtract"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "multiply",
                  "Next": "state.process.operator.multiply"
                },
                {
                  "Variable": "$.operator",
                  "StringEquals": "divide",
                  "Next": "state.process.operator.divide"
                }
              ],
              "Default": "state.process.operator.unknown"
            },
            "state.process.operator.add": {
              "Type": "Task",
              "Comment": "Performs an addition on the operands provided",
              "Next": "state.process.displayResult",
              "Resource" : "${Calculator.Arn}"
            },
            "state.process.operator.subtract": {
              "Type": "Task",
              "Comment": "Performs an subtraction on the operands provided",
              "Next": "state.process.displayResult",
              "Resource" : "${Calculator.Arn}"
            },
            "state.process.operator.multiply": {
              "Type": "Task",
              "Comment": "Performs an multiplication on the operands provided",
              "Next": "state.process.displayResult",
              "Resource" : "${Calculator.Arn}"
            },
            "state.process.operator.divide": {
              "Type": "Task",
              "Comment": "Performs an division on the operands provided",
              "Next": "state.process.displayResult",
              "Resource" : "${Calculator.Arn}"
            },
            "state.process.operator.unknown": {
              "Type": "Fail",
              "Error": "UNKNOWN_OPERATOR",
              "Cause" : "The operator provided is not supported"
            },
            "state.process.displayResult": {
              "Type": "Pass",
              "Next": "state.process.complete"
            },
            "state.process.complete": {
              "Type": "Pass",
              "End": true
            }
          }
        }
      RoleArn: !GetAtt StepFunctionRole.Arn

  # Now, a simple Lambda calculator function.
  Calculator:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: Calculator
      Description: Part of a StepFunction demo
      MemorySize: 128
      Timeout: 4
      Role: !GetAtt LambdaFunctionRole.Arn
      Runtime: nodejs20.x
      Handler: index.handler
      Code:
        ZipFile: !Sub |
          'use strict';
          console.log('Loading function');
          exports.handler = (event, context, callback) => {
              console.log('Received event:', JSON.stringify(event, null, 2));
              var operator = event.operator;
              var operand1 = event.operands[0];
              var operand2 = event.operands[1];
              var result = 0;
              if (operator == 'add') {
                result = operand1 + operand2;
              }
              else if (operator == 'subtract') {
                result = operand1 - operand2;
              }
              else if (operator == 'multiply') {
                result = operand1 * operand2;
              }
              else if (operator == 'divide') {
                result = operand1 / operand2;
              }
              console.log('Returning:', result);
              callback(null, result);
          };

  # This Role allows the Lambda function to make API calls if needed.
  LambdaFunctionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: 2012-10-17
        Statement:
          Effect: Allow
          Principal:
            Service: lambda.amazonaws.com
          Action: sts:AssumeRole

  # This Policy is attached to the LambdaFunctionRole.
  # Basic permissions for CloudWatch Logs, expand as needed.
  LambdaFunctionPolicy:
    Type: AWS::IAM::Policy
    Properties:
      PolicyName: LambdaFunctionPolicy
      PolicyDocument:
        Version: 2012-10-17
        Statement:
          Effect: Allow
          Action:
            - logs:CreateLogStream
            - logs:PutLogEvents
          Resource: "*"
      Roles:
        -  !Ref LambdaFunctionRole

  StepFunctionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: 2012-10-17
        Statement:
          Effect: Allow
          Principal:
            Service: !Join ["", ["states.", !Ref "AWS::Region", ".amazonaws.com"]]
          Action: "sts:AssumeRole"

  # This Policy is attached to the StepFunctionRole.
  # Basic permissions to call Lambda.
  StepFunctionPolicy:
    Type: AWS::IAM::Policy
    Properties:
      PolicyName: StepFunctionPolicy
      PolicyDocument:
        Version: 2012-10-17
        Statement:
          Effect: Allow
          Action:
            - lambda:InvokeFunction
          Resource: "*"
      Roles:
        -  !Ref StepFunctionRole

  # CloudWatch Logs Groups are created automatically once Lambdas write output,
  # but they are easier to cleanup when they are part of the stack.
  # So make one for the Lambda function:
  CloudwatchLogsGroupForLambda:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub /aws/lambda/${Calculator}
      RetentionInDays: 3

Outputs:

  SampleInput:
    Description:  Some sample input
    Value: '{"operator": "add", "operands": [1,2]}'

AWSTemplateFormatVersion: "2010-09-09"
Description: Generates IOT Core policy for Device Onboarding
Resources:
  #=======================================================
  #
  #                    IOT Core Policy
  #
  #=======================================================

  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      Path: /
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - lambda.amazonaws.com
            Action:
              - sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName:
            Fn::Sub: iot-core-policy-generator-policy-${AWS::Region}
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                Resource:
                  - "*"

  IotPolicyGenerator:
    Type: AWS::Lambda::Function
    Properties:
      FunctionName: IotPolicyGenerator
      Handler: index.handler
      Runtime: nodejs24.x
      MemorySize: 128
      Timeout: 15
      Role:
        Fn::GetAtt:
          - LambdaExecutionRole
          - Arn
      TracingConfig:
        Mode: Active
      Code:
        ZipFile: |
          const { IoTClient, CreatePolicyCommand } = require("@aws-sdk/client-iot");
          const response = require('cfn-response');
          exports.handler = async function(event, context) {
              console.log("REQUEST RECEIVED:\n" + JSON.stringify(event));
              if (event.RequestType == "Delete") {
                  await sendResponse(event, context, response.SUCCESS, {});
                  return;
              }
              const policyName = "device-onboarding";
              const region = process.env.AWS_REGION;
              const awsAccountId = context.invokedFunctionArn.split(':')[4];
              const policyDocument = `{
                  "Version": "2012-10-17",
                  "Statement": [
                  {
                      "Effect": "Allow",
                      "Action": [
                      "iot:Connect"
                      ],
                      "Resource": [
                      "arn:aws:iot:${region}:${awsAccountId}:client/\${iot:Connection.Thing.ThingName}"
                      ]
                  },
                  {
                      "Effect": "Allow",
                      "Action": [
                      "iot:Publish",
                      "iot:Receive"
                      ],
                      "Resource": [
                      "arn:aws:iot:${region}:${awsAccountId}:topic/\${iot:Connection.Thing.ThingName}/*"
                      ]
                  },
                  {
                      "Effect": "Allow",
                      "Action": [
                      "iot:Subscribe"
                      ],
                      "Resource": [
                      "arn:aws:iot:${region}:${awsAccountId}:topicfilter/\${iot:Connection.Thing.ThingName}/*"
                      ]
                  }
                  ]
              }`;
              console.log("Policy document:\n", policyDocument);
              const iot = new IoTClient();
              try {
                  const data = await iot.send(new CreatePolicyCommand({policyName, policyDocument}));
                  const responseData = { policyName: data.policyName };
                  console.log('Response data: ' + JSON.stringify(responseData));
                  await sendResponse(event, context, response.SUCCESS, responseData);
              } catch (err) {
                  const responseData = { Error: "createIoTPolicy call failed" };
                  console.error(responseData.Error + ":\n", err);
                  await sendResponse(event, context, response.FAILED, responseData);
              }
          };
          // Wrap cfn-response's callback-based send so it can be awaited in the async handler.
          function sendResponse(event, context, status, data) {
              return new Promise(function(resolve) {
                  const done = context.done;
                  context.done = function() {
                      resolve();
                      if (done) {
                          done.apply(context, arguments);
                      }
                  };
                  response.send(event, context, status, data);
              });
          }
  IoTPolicy:
    Type: Custom::IotPolicyGenerator
    Properties:
      ServiceToken:
        Fn::GetAtt:
          - IotPolicyGenerator
          - Arn

Outputs:
  #=======================================================
  #
  #                 CloudFormation Outputs
  #
  #=======================================================
  IOTCorePolicyName:
    Description: The name of the newly created IOT Core Policy
    Value:
      Fn::GetAtt:
        - IoTPolicy
        - policyName

