            [
              "{",
              "    \"Comment\": \"A Hello World example of the Amazon States Language using Pass states\",",
              "    \"StartAt\": \"Hello\",",
              "    \"States\": {",
              "        \"Hello\": {",
              "            \"Next\": \"World\",",
              "            \"Result\": \"Hello\",",
              "            \"Type\": \"Pass\"",
              "        },",
              "        \"World\": {",
              "            \"End\": true,",
              "            \"Result\": \"World\",",
              "            \"Type\": \"Pass\"",
              "        }",
              "    }",
              "}"
