              "    \"States\": {",
              "        \"Hello\": {",
              "            \"Next\": \"World\",",
              "            \"Result\": \"Hello\",",
              "            \"Type\": \"Pass\"",
              "        },",
              "        \"World\": {",
              "            \"End\": true,",
              "            \"Result\": \"World\",",
              "            \"Type\": \"Pass\"",
              "        }",
              "    }",
              "}"
