{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Description": "Provides the base security, IAM, and access configuration for the AWS account",
  "Metadata": {
    "Stack": {
      "Value": "1"
    },
    "VersionDate": {
      "Value": "20160510"
    },
    "Identifier": {
      "Value": "template-iam"
    },
    "Input": {
      "Description": "CloudTrail bucket name"
    },
    "Output": {
      "Description": "Outputs ID of all deployed resources"
    }
  },
  "Resources": {
    "rSysAdminRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Statement": [{
            "Effect": "Allow",
            "Principal": {
              "Service": [
                "ec2.amazonaws.com"
              ]

            },
            "Action": [
              "sts:AssumeRole"
            ]
          }]
        }
      }
    },

    "rSysAdminProfile": {
      "Type": "AWS::IAM::InstanceProfile",
      "DependsOn": "rSysAdminRole",
      "Properties": {
        "Path": "/",
        "Roles": [{
          "Ref": "rSysAdminRole"
        }]
      }
    },

    "rSysAdmin": {
      "Type": "AWS::IAM::Group",
      "Properties": {
        "Path": "/"
      }
    },

    "rSysAdminPolicy": {
      "Type": "AWS::IAM::ManagedPolicy",
      "Properties": {
        "PolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [{
            "Effect": "Allow",
            "NotAction": "iam:*",
            "Resource": "*",
            "Condition": {
              "Bool": {
                "aws:MultiFactorAuthPresent": "true"
              }
            }
          }, {
            "Effect": "Deny",
            "Action": "aws-portal:*Billing",
            "Resource": "*"
          }, {
            "Effect": "Deny",
            "Action": ["cloudtrail:DeleteTrail",
              "cloudtrail:StopLogging",
              "cloudtrail:UpdateTrail"
            ],
            "Resource": "*"
          }, {
            "Effect": "Deny",
            "Action": [
              "kms:Create*",
              "kms:Revoke*",
              "kms:Enable*",
              "kms:Get*",
              "kms:Disable*",
              "kms:Delete*",
              "kms:Put*",
              "kms:Update*"
            ],
            "Resource": "*"
          }]
        },
        "Roles": [{
          "Ref": "rSysAdminRole"
        }],
        "Groups": [{
          "Ref": "rSysAdmin"
        }]
      }
    },

    "rIAMAdminGroup": {
      "Type": "AWS::IAM::Group",
      "Properties": {
        "Path": "/"
      }
    },

    "rIAMAdminRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Statement": [{
            "Effect": "Allow",
            "Principal": {
              "Service": [
                "ec2.amazonaws.com"
              ]

            },
            "Action": [
              "sts:AssumeRole"
            ]
          }]
        }
      }
    },

    "rIAMAdminProfile": {
      "Type": "AWS::IAM::InstanceProfile",
      "DependsOn": "rIAMAdminRole",
      "Properties": {
        "Path": "/",
        "Roles": [{
          "Ref": "rIAMAdminRole"
        }]
      }
    },

    "rIAMAdminPolicy": {
      "Type": "AWS::IAM::ManagedPolicy",
      "Properties": {
        "PolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [{
              "Effect": "Allow",
              "Action": "iam:*",
              "Resource": "*",
              "Condition": {
                "Bool": {
                  "aws:MultiFactorAuthPresent": "true"
                }
              }
            }, {
              "Effect": "Deny",
              "Action": "aws-portal:*Billing",
              "Resource": "*"
            }

          ]
        },
        "Roles": [{
          "Ref": "rIAMAdminRole"
        }],
        "Groups": [{
          "Ref": "rIAMAdminGroup"
        }]
      }
    },

    "rInstanceOpsGroup": {
      "Type": "AWS::IAM::Group",
      "Properties": {
        "Path": "/"
      }
    },

    "rInstanceOpsRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Statement": [{
            "Effect": "Allow",
            "Principal": {
              "Service": [
                "ec2.amazonaws.com"
              ]

            },
            "Action": [
              "sts:AssumeRole"
            ]
          }]
        }
      }
    },

    "rInstanceOpsProfile": {
      "Type": "AWS::IAM::InstanceProfile",
      "DependsOn": "rInstanceOpsRole",
      "Properties": {
        "Path": "/",
        "Roles": [{
          "Ref": "rInstanceOpsRole"
        }]
      }
    },

    "rInstanceOpsPolicy": {
      "Type": "AWS::IAM::ManagedPolicy",
      "Properties": {
        "PolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [{
            "Action": "ec2:*",
            "Effect": "Allow",
            "Resource": "*"
          }, {
            "Effect": "Allow",
            "Action": "elasticloadbalancing:*",
            "Resource": "*"
          }, {
            "Effect": "Allow",
            "Action": "cloudwatch:*",
            "Resource": "*"
          }, {
            "Effect": "Allow",
            "Action": "autoscaling:*",
            "Resource": "*"
          }, {
            "Effect": "Deny",
            "Action": ["ec2:CreateVpc*",
              "ec2:DeleteVpc*",
              "ec2:ModifyVpc*",
              "ec2:CreateSubnet*",
              "ec2:DeleteSubnet*",
              "ec2:ModifySubnet*",
              "ec2:Create*Route*",
              "ec2:DeleteRoute*",
              "ec2:AssociateRoute*",
              "ec2:ReplaceRoute*",
              "ec2:CreateVpn*",
              "ec2:DeleteVpn*",
              "ec2:AttachVpn*",
              "ec2:DetachVpn*",
              "ec2:CreateNetworkAcl*",
              "ec2:DeleteNetworkAcl*",
              "ec2:ReplaceNetworkAcl*",
              "ec2:*Gateway*",
              "ec2:*PeeringConnection*"
            ],
            "Resource": "*"
          }, {
            "Effect": "Deny",
            "Action": "aws-portal:*Billing",
            "Resource": "*"
          }, {
            "Effect": "Deny",
            "Action": [
              "kms:Create*",
              "kms:Revoke*",
              "kms:Enable*",
              "kms:Get*",
              "kms:Disable*",
              "kms:Delete*",
              "kms:Put*",
              "kms:Update*"
            ],
            "Resource": "*"
          }]

        },
        "Roles": [{
          "Ref": "rInstanceOpsRole"
        }],
        "Groups": [{
          "Ref": "rInstanceOpsGroup"
        }]
      }
    },

    "rReadOnlyAdminGroup": {
      "Type": "AWS::IAM::Group",
      "Properties": {
        "Path": "/"
      }
    },

    "rReadOnlyAdminRole": {
      "Type": "AWS::IAM::Role",
